ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true, ADD COLUMN IF NOT EXISTS telefone text DEFAULT '';
CREATE OR REPLACE FUNCTION app_private.my_empresa_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT empresa_id FROM public.profiles WHERE id=auth.uid() AND ativo $$;
CREATE OR REPLACE FUNCTION app_private.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT app_private.my_empresa_id() IS NOT NULL AND app_private.has_role(auth.uid(),'admin') $$;
REVOKE ALL ON FUNCTION app_private.is_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION app_private.is_admin() TO authenticated;
ALTER TABLE public.empresas ADD COLUMN IF NOT EXISTS cnpj text DEFAULT '', ADD COLUMN IF NOT EXISTS telefone text DEFAULT '', ADD COLUMN IF NOT EXISTS whatsapp text DEFAULT '', ADD COLUMN IF NOT EXISTS email text DEFAULT '', ADD COLUMN IF NOT EXISTS endereco text DEFAULT '', ADD COLUMN IF NOT EXISTS logo_url text DEFAULT '', ADD COLUMN IF NOT EXISTS dias_alerta_renovacao integer NOT NULL DEFAULT 60;
