UPDATE public.veiculos SET ano_modelo=ano WHERE ano_modelo IS NULL AND ano IS NOT NULL;
CREATE TABLE public.seguradoras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), nome text NOT NULL, cnpj text DEFAULT '', ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(empresa_id,nome));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.seguradoras TO authenticated; GRANT ALL ON public.seguradoras TO service_role;
