ALTER TABLE public.apolices ADD COLUMN IF NOT EXISTS ramo text NOT NULL DEFAULT 'Auto', ADD COLUMN IF NOT EXISTS seguradora_id uuid REFERENCES public.seguradoras(id), ADD COLUMN IF NOT EXISTS forma_pagamento text DEFAULT '', ADD COLUMN IF NOT EXISTS parcelas_qtd integer, ADD COLUMN IF NOT EXISTS comissao_valor numeric(12,2), ADD COLUMN IF NOT EXISTS responsavel_id uuid, ADD COLUMN IF NOT EXISTS apolice_anterior_id uuid REFERENCES public.apolices(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS renovacao_status text NOT NULL DEFAULT 'Pendente', ADD COLUMN IF NOT EXISTS renovacao_obs text DEFAULT '', ADD COLUMN IF NOT EXISTS is_demo boolean NOT NULL DEFAULT false;
