CREATE POLICY comissoes_insert ON public.comissoes FOR INSERT TO authenticated WITH CHECK (empresa_id=app_private.my_empresa_id() AND (app_private.is_admin() OR responsavel_id=auth.uid()) AND EXISTS(SELECT 1 FROM public.apolices a WHERE a.id=apolice_id AND a.empresa_id=app_private.my_empresa_id()));
