CREATE TABLE public.documentos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), cliente_id uuid REFERENCES public.clientes(id) ON DELETE CASCADE, veiculo_id uuid REFERENCES public.veiculos(id) ON DELETE SET NULL, apolice_id uuid REFERENCES public.apolices(id) ON DELETE SET NULL, sinistro_id uuid REFERENCES public.sinistros(id) ON DELETE SET NULL, nome text NOT NULL, categoria text NOT NULL DEFAULT 'Outro', caminho text NOT NULL UNIQUE, tamanho bigint, tipo_mime text DEFAULT '', enviado_por uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documentos TO authenticated; GRANT ALL ON public.documentos TO service_role;
ALTER TABLE public.documentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY documentos_select ON public.documentos FOR SELECT TO authenticated USING (empresa_id=app_private.my_empresa_id());
CREATE POLICY documentos_insert ON public.documentos FOR INSERT TO authenticated WITH CHECK (empresa_id=app_private.my_empresa_id() AND enviado_por=auth.uid() AND caminho LIKE app_private.my_empresa_id()::text||'/%' AND (cliente_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=cliente_id AND c.empresa_id=app_private.my_empresa_id())) AND (veiculo_id IS NULL OR EXISTS(SELECT 1 FROM public.veiculos v WHERE v.id=veiculo_id AND v.empresa_id=app_private.my_empresa_id())) AND (apolice_id IS NULL OR EXISTS(SELECT 1 FROM public.apolices a WHERE a.id=apolice_id AND a.empresa_id=app_private.my_empresa_id())) AND (sinistro_id IS NULL OR EXISTS(SELECT 1 FROM public.sinistros s WHERE s.id=sinistro_id AND s.empresa_id=app_private.my_empresa_id())));
CREATE OR REPLACE FUNCTION app_private.proteger_documento() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.empresa_id<>OLD.empresa_id OR NEW.caminho<>OLD.caminho OR NEW.enviado_por IS DISTINCT FROM OLD.enviado_por THEN RAISE EXCEPTION 'Não é permitido mudar a origem do arquivo'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION app_private.proteger_documento() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER proteger_documento BEFORE UPDATE ON public.documentos FOR EACH ROW EXECUTE FUNCTION app_private.proteger_documento();
CREATE POLICY documentos_update ON public.documentos FOR UPDATE TO authenticated USING (empresa_id=app_private.my_empresa_id() AND (app_private.is_admin() OR enviado_por=auth.uid())) WITH CHECK (empresa_id=app_private.my_empresa_id() AND caminho LIKE app_private.my_empresa_id()::text||'/%' AND (cliente_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=cliente_id AND c.empresa_id=app_private.my_empresa_id())) AND (veiculo_id IS NULL OR EXISTS(SELECT 1 FROM public.veiculos v WHERE v.id=veiculo_id AND v.empresa_id=app_private.my_empresa_id())) AND (apolice_id IS NULL OR EXISTS(SELECT 1 FROM public.apolices a WHERE a.id=apolice_id AND a.empresa_id=app_private.my_empresa_id())) AND (sinistro_id IS NULL OR EXISTS(SELECT 1 FROM public.sinistros s WHERE s.id=sinistro_id AND s.empresa_id=app_private.my_empresa_id())));
