DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['seguradoras','condutores','parcelas','comissoes','documentos','mensagens','convites'] LOOP EXECUTE format('CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t); END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['clientes','leads','veiculos','apolices','tarefas','historico_contatos','sinistros'] LOOP EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I',CASE WHEN t='historico_contatos' THEN 'historico_empresa' ELSE t||'_empresa' END,t); END LOOP; END $$;
