DROP POLICY IF EXISTS profiles_edit ON public.profiles; REVOKE UPDATE ON public.profiles FROM authenticated; GRANT UPDATE(nome,telefone) ON public.profiles TO authenticated; CREATE POLICY profiles_edit ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid() AND empresa_id=app_private.my_empresa_id()) WITH CHECK (id=auth.uid() AND empresa_id=app_private.my_empresa_id());
REVOKE INSERT,UPDATE ON public.empresas FROM authenticated; GRANT UPDATE(nome,cnpj,telefone,whatsapp,email,endereco,logo_url,dias_alerta_renovacao) ON public.empresas TO authenticated;
CREATE OR REPLACE FUNCTION app_private.criar_mensagens_padrao(_empresa uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.mensagens(empresa_id,chave,titulo,texto) VALUES (_empresa,'primeiro_contato','Primeiro contato','Olá, {nome}! Tudo bem?'),(_empresa,'renovacao','Renovação','Olá, {nome}! Seu seguro está próximo do vencimento.'),(_empresa,'documento','Documentos','Olá, {nome}! Precisamos de alguns documentos.'),(_empresa,'pos_venda','Pós-venda','Olá, {nome}! Sua apólice já está ativa.'),(_empresa,'sinistro','Sinistro','Olá, {nome}! Estou acompanhando seu sinistro.') ON CONFLICT (empresa_id,chave) DO NOTHING $$;
REVOKE ALL ON FUNCTION app_private.criar_mensagens_padrao(uuid) FROM PUBLIC,anon,authenticated;
SELECT app_private.criar_mensagens_padrao(id) FROM public.empresas;
CREATE OR REPLACE FUNCTION app_private.bootstrap_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e uuid; r public.app_role:='admin'; invite public.convites%ROWTYPE; n text; BEGIN SELECT * INTO invite FROM public.convites WHERE lower(email)=lower(NEW.email) AND aceito_em IS NULL ORDER BY created_at DESC LIMIT 1; n:=COALESCE(NULLIF(NEW.raw_user_meta_data->>'nome',''),NULLIF(NEW.raw_user_meta_data->>'full_name',''),NULLIF(invite.nome,''),split_part(COALESCE(NEW.email,''),'@',1)); IF invite.id IS NOT NULL THEN e:=invite.empresa_id; r:=invite.role; UPDATE public.convites SET aceito_em=now() WHERE id=invite.id; ELSE INSERT INTO public.empresas(nome) VALUES(COALESCE(NULLIF(NEW.raw_user_meta_data->>'empresa',''),'Minha corretora')) RETURNING id INTO e; PERFORM app_private.criar_mensagens_padrao(e); END IF; INSERT INTO public.profiles(id,empresa_id,nome,email) VALUES(NEW.id,e,n,COALESCE(NEW.email,'')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,r); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION app_private.bootstrap_user() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.definir_usuario(_user_id uuid,_role public.app_role,_ativo boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT app_private.is_admin() THEN RAISE EXCEPTION 'Apenas administradores.'; END IF; IF _user_id=auth.uid() THEN RAISE EXCEPTION 'Você não pode alterar o próprio perfil.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND empresa_id=app_private.my_empresa_id()) THEN RAISE EXCEPTION 'Usuário não encontrado.'; END IF; DELETE FROM public.user_roles WHERE user_id=_user_id; INSERT INTO public.user_roles(user_id,role) VALUES(_user_id,_role); UPDATE public.profiles SET ativo=_ativo WHERE id=_user_id; END $$;
REVOKE ALL ON FUNCTION public.definir_usuario(uuid,public.app_role,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.definir_usuario(uuid,public.app_role,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.apolice_renovada() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.apolice_anterior_id IS NOT NULL THEN UPDATE public.apolices SET status='Renovada',renovacao_status='Renovada' WHERE id=NEW.apolice_anterior_id AND empresa_id=NEW.empresa_id; END IF; RETURN NEW; END $$;
CREATE TRIGGER apolice_renovada AFTER INSERT ON public.apolices FOR EACH ROW EXECUTE FUNCTION app_private.apolice_renovada();
CREATE OR REPLACE FUNCTION public.gerar_parcelas(_apolice_id uuid,_qtd integer DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.apolices%ROWTYPE; n integer; i integer; v numeric; c numeric; BEGIN SELECT * INTO a FROM public.apolices WHERE id=_apolice_id AND empresa_id=app_private.my_empresa_id(); IF a.id IS NULL THEN RAISE EXCEPTION 'Apólice não encontrada.'; END IF; IF EXISTS(SELECT 1 FROM public.parcelas WHERE apolice_id=a.id) THEN RAISE EXCEPTION 'Esta apólice já possui parcelas.'; END IF; n:=COALESCE(_qtd,a.parcelas_qtd,1); IF n<1 OR n>24 THEN RAISE EXCEPTION 'Quantidade inválida.'; END IF; FOR i IN 1..n LOOP v:=CASE WHEN i=n THEN a.premio-trunc(a.premio/n,2)*(n-1) ELSE trunc(a.premio/n,2) END; INSERT INTO public.parcelas(empresa_id,apolice_id,numero,vencimento,valor,is_demo) VALUES(a.empresa_id,a.id,i,(a.inicio+make_interval(months=>i-1))::date,v,a.is_demo); c:=COALESCE(a.comissao_valor,round(a.premio*COALESCE(a.comissao_percentual,0)/100,2)); IF c>0 THEN INSERT INTO public.comissoes(empresa_id,apolice_id,parcela,percentual,valor,data_prevista,responsavel_id,is_demo) VALUES(a.empresa_id,a.id,i,a.comissao_percentual,CASE WHEN i=n THEN c-trunc(c/n,2)*(n-1) ELSE trunc(c/n,2) END,(a.inicio+make_interval(months=>i-1)+interval '30 days')::date,COALESCE(a.responsavel_id,auth.uid()),a.is_demo); END IF; END LOOP; UPDATE public.apolices SET parcelas_qtd=n WHERE id=a.id; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.gerar_parcelas(uuid,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.gerar_parcelas(uuid,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.converter_lead(_lead_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE l public.leads%ROWTYPE; c uuid; BEGIN SELECT * INTO l FROM public.leads WHERE id=_lead_id AND empresa_id=app_private.my_empresa_id() FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Lead não encontrado.'; END IF; IF l.cliente_id IS NOT NULL THEN RETURN l.cliente_id; END IF; INSERT INTO public.clientes(empresa_id,tipo,nome,documento,telefone,whatsapp,email,cidade,observacoes,responsavel_id,is_demo) VALUES(l.empresa_id,CASE WHEN length(regexp_replace(COALESCE(l.documento,''),'\D','','g'))=14 THEN 'PJ' ELSE 'PF' END,l.nome,l.documento,l.telefone,l.whatsapp,l.email,l.cidade,l.observacoes,COALESCE(l.responsavel_id,auth.uid()),l.is_demo) RETURNING id INTO c; UPDATE public.leads SET cliente_id=c,status='Vendido' WHERE id=l.id; UPDATE public.historico_contatos SET cliente_id=c WHERE lead_id=l.id AND cliente_id IS NULL; UPDATE public.tarefas SET cliente_id=c WHERE lead_id=l.id AND cliente_id IS NULL; INSERT INTO public.historico_contatos(empresa_id,cliente_id,lead_id,tipo,descricao,usuario_id,is_demo) VALUES(l.empresa_id,c,l.id,'Sistema','Lead convertido em cliente.',auth.uid(),l.is_demo); RETURN c; END $$;
REVOKE ALL ON FUNCTION public.converter_lead(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.converter_lead(uuid) TO authenticated;
CREATE POLICY documentos_storage_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='documentos' AND (storage.foldername(name))[1]=app_private.my_empresa_id()::text);
CREATE POLICY documentos_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='documentos' AND (storage.foldername(name))[1]=app_private.my_empresa_id()::text);
CREATE POLICY documentos_storage_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='documentos' AND (storage.foldername(name))[1]=app_private.my_empresa_id()::text AND (app_private.is_admin() OR owner=auth.uid()));
CREATE INDEX parcelas_empresa_venc ON public.parcelas(empresa_id,vencimento); CREATE INDEX comissoes_empresa_prev ON public.comissoes(empresa_id,data_prevista); CREATE INDEX documentos_cliente ON public.documentos(empresa_id,cliente_id); CREATE INDEX atividades_empresa_data ON public.atividades(empresa_id,created_at DESC);